effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN: all reads go through the layer transform, so the grade
// follows the layer rather than the composition frame.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

// Un-premultiply, grade in straight colour, re-premultiply at the end.
float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

vec3 c = sat3v(sc);
float l0 = lum(c);

// ---- shared level stretch ----------------------------------------------
// White Point below Black Point is not representable, so clamp the span.
c = sat3v((c - vec3(blackPoint)) / max(whitePoint - blackPoint, 0.02));
c = sat3v(c + vec3(lift));

vec3 g = vec3(gainR, gainG, gainB);
vec3 o = vec3(offsetR, offsetG, offsetB);

// ---- combine ------------------------------------------------------------
vec3 v;
if (multMode <= 0){
v = c * g;
} else if (multMode <= 1){
v = c + o;
} else if (multMode <= 2){
// Screen: 1-(1-a)(1-b). An offset can only ever brighten here, which is what
// makes this the safe mode for a shadow lift that must not crush.
v = vec3(1.0) - (vec3(1.0) - c) * (vec3(1.0) - o);
} else {
// Overlay Boost: multiply, then soft-limit anything above white so the
// highlight keeps its gradient instead of turning into a flat patch.
v = c * g;
v = v / (vec3(1.0) + max(v - vec3(1.0), vec3(0.0)) * 0.55);
}
v = sat3v(v);

// ---- per-channel gamma --------------------------------------------------
// 1/gamma so a value above 1.0 brightens, which is how a curve control should
// read. Each channel gets its own exponent.
v = sat3v(pow(max(v, vec3(0.0)),
              vec3(1.0 / max(gammaR, 0.05),
                   1.0 / max(gammaG, 0.05),
                   1.0 / max(gammaB, 0.05))));

// ---- preserve luma ------------------------------------------------------
// Rescale so the output carries the input's luminance. Without it a red gain
// also reads as a global exposure change and the slider is unusable.
float l1 = lum(v);
v = sat3v(mix(v, v * (l0 / max(l1, 1e-4)), preserveLuma));

vec3  col = mix(sc, v, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
